local Util = require("arrowlake.util")

local M = {}

-- Extras are for apps Omarchy does not theme itself. Terminals, btop and tmux
-- are generated by Omarchy from colors.toml. The remaining generators either
-- need multiple files (Yazi), computed scales (OpenCode), or an app-specific
-- import format (Sublime/Silicon, Codex, WezTerm).
---@type { name: string, ext: string }[]
M.extras = {
  { name = "opencode", ext = "json" },
  { name = "sublime", ext = "tmTheme" },
  { name = "yazi", ext = "toml" },
}

-- Theme-local files that are not general-purpose extras.
---@type { name: string, file: string }[]
M.theme_files = {
  { name = "codex", file = "codex.txt" },
  { name = "wezterm", file = "wezterm.json" },
}

--- Validate an additional artifact path so generators cannot write outside
--- the extra's output directory.
---@param path string
---@return boolean ok
---@return string? err
local function is_safe_artifact_path(path)
  if type(path) ~= "string" or path == "" then
    return false, "artifact path must be a non-empty string"
  end
  if path:sub(1, 1) == "/" or path:sub(1, 1) == "\\" or path:match("^%a:[/\\]") then
    return false, "artifact path must be relative: " .. path
  end
  for part in path:gmatch("[^/\\]+") do
    if part == ".." then
      return false, "artifact path must not traverse parents: " .. path
    end
  end
  return true
end

---Generate every extra and the Omarchy theme files.
---@param opts? { root?: string }
function M.build(opts)
  local root = (opts and opts.root or "."):gsub("/+$", "")
  local prefix = root == "" and "" or (root .. "/")

  local Omarchy = require("arrowlake.extra.omarchy")

  local function write(path, contents)
    print("[write] " .. path)
    Util.write(prefix .. path, contents)
  end

  for _, style in ipairs({ "dark", "light" }) do
    local colors = require("arrowlake.colors").setup(style)
    colors._style = style

    local slug = Omarchy.slug(style)
    local theme_dir = "omarchy/themes/" .. slug
    write(theme_dir .. "/colors.toml", Omarchy.colors_toml(colors))
    write(theme_dir .. "/neovim.lua", Omarchy.neovim(style))

    for _, extra in ipairs(M.theme_files) do
      local mod = require("arrowlake.extra." .. extra.name)
      write(theme_dir .. "/" .. extra.file, mod.generate(colors))
    end

    for _, extra in ipairs(M.extras) do
      local mod = require("arrowlake.extra." .. extra.name)
      local primary, artifacts = mod.generate(colors)

      if primary then
        write(("extras/%s/arrowlake_%s.%s"):format(extra.name, style, extra.ext), primary)
      end

      if artifacts then
        local out_dir = ("extras/%s"):format(extra.name)
        for _, artifact in ipairs(artifacts) do
          local ok, err = is_safe_artifact_path(artifact and artifact.path)
          assert(ok, err)
          assert(type(artifact.content) == "string", "artifact content must be a string")
          write(out_dir .. "/" .. artifact.path, artifact.content)
        end
      end
    end
  end
end

return M
